'use strict';
// TEST-ONLY stand-in for @node-rs/argon2 (scrypt-based) so service code can run
// where npm packages can't be installed. Production uses real Argon2id.
const crypto = require('node:crypto');
exports.hash = async (pw) => {
  const salt = crypto.randomBytes(16);
  const key = crypto.scryptSync(pw, salt, 32, { N: 1024 });
  return `$test-scrypt$${salt.toString('hex')}$${key.toString('hex')}`;
};
exports.verify = async (hash, pw) => {
  const [, , salt, key] = hash.split('$');
  const k = crypto.scryptSync(pw, Buffer.from(salt, 'hex'), 32, { N: 1024 });
  return crypto.timingSafeEqual(k, Buffer.from(key, 'hex'));
};
